import type { Source } from "./Core";
/**
 * Creates a pullable callbag source that emits
 * the value indicated and then ends.
 *
 * Marble diagram:
 *   {just(a)}
 *   " a |"
 *
 * @param value The value to emit.
 * @returns A pullable callbag source that emits a
 *     the value indicated and then ends.
 *
 * @internal
 */
export declare const just: <T>(value: T) => Source<T, never>;
